function createStreamlineIcon(name: keyof typeof iconDefinitions): LucideIcon {
  const definition = iconDefinitions[name];

  const Component = React.forwardRef<SVGSVGElement, StreamlineIconProps>(
    ({ size = 24, color, strokeWidth: _strokeWidth, absoluteStrokeWidth: _absoluteStrokeWidth, style, children: _children, ...props }, ref) => {
      const transform = definition.rotate ? 'rotate(' + definition.rotate + 'deg)' : undefined;

      return (
        <svg
          ref={ref}
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox={definition.viewBox}
          fill="none"
          aria-hidden={props['aria-label'] ? undefined : true}
          focusable="false"
          color={color}
          style={{ ...style, transform: [style?.transform, transform].filter(Boolean).join(' ') || undefined }}
          {...props}
          dangerouslySetInnerHTML={{ __html: definition.body }}
        />
      );
    },
  );

  Component.displayName = name;
  return Component;
}

